<?php

namespace App\Services;

use App\Models\PayPeriod;
use App\Models\Scheme;
use App\Models\User;
use App\Payroll\PayPeriodPlan;
use App\Payroll\Statutory\TaxYear;
use App\Support\Audit;
use Carbon\Carbon;
use Illuminate\Database\QueryException;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;

/**
 * Pay periods: generated by hand once a year per scheme from the scheme's pay settings, then Open -> Closed -> (Locked by the pay run).
 * Pay inputs and pay runs pick a stored period and must call assertOpen() before changing anything that belongs to it.
 */
class PayPeriodService
{
    public static function startMonth(): int
    {
        return (int) config('statutory.tax_year_start_month', 4);
    }

    /** @return array<int, string> tax year start year => "Y/A 2026/27 (Apr 2026 to Mar 2027)" */
    public function taxYearOptions(): array
    {
        $current = TaxYear::for(today(), self::startMonth())['year'];
        $out = [];
        foreach (range($current - 2, $current + 1) as $y) {
            $start = Carbon::create($y, self::startMonth(), 1);
            $out[$y] = TaxYear::for($start, self::startMonth())['label'].' ('.$start->format('M Y').' to '.$start->copy()->addMonthsNoOverflow(11)->format('M Y').')';
        }

        return $out;
    }

    /**
     * Creates the missing periods of a tax year for a scheme (safe to repeat). With $refresh, OPEN periods whose dates no longer match the
     * scheme's settings are updated too. Closed and locked periods are never changed.
     *
     * @return array{created: int, updated: int, unchanged: int, removed: int, kept: int, extra: int, skipped: array<int, string>}
     */
    public function generate(Scheme $scheme, int $taxYearStart, User $by, bool $refresh = false): array
    {
        if ($taxYearStart < 2000 || $taxYearStart > 2100) {
            throw ValidationException::withMessages(['year' => 'Choose a valid tax year.']);
        }
        $label = TaxYear::for(Carbon::create($taxYearStart, self::startMonth(), 1), self::startMonth())['label'];

        return DB::transaction(function () use ($scheme, $taxYearStart, $label, $by, $refresh) {
            Scheme::whereKey($scheme->id)->lockForUpdate()->firstOrFail(); // serialise generation per scheme
            $r = ['created' => 0, 'updated' => 0, 'unchanged' => 0, 'removed' => 0, 'kept' => 0, 'extra' => 0, 'skipped' => []];

            foreach (PayPeriodPlan::taxYearMonths($taxYearStart, self::startMonth()) as [$y, $m]) {
                $first = Carbon::create($y, $m, 1)->startOfDay();
                $settings = $scheme->paySettingsAt($first);
                if (! $settings) {
                    $r['skipped'][] = $first->format('M Y');
                    continue;
                }

                $rows = PayPeriodPlan::forMonth($settings->toCalendar(), $settings->statutory_timing, $y, $m);
                $existing = PayPeriod::withoutGlobalScopes()->where('scheme_id', $scheme->id)->where('year', $y)->where('month', $m)->get()->keyBy('cycle_no');

                foreach ($rows as $row) {
                    $attrs = $row + ['scheme_pay_setting_id' => $settings->id, 'tax_year_start' => $taxYearStart, 'tax_year_label' => $label];
                    $p = $existing->get($row['cycle_no']);

                    if (! $p) {
                        (new PayPeriod)->forceFill($attrs + ['scheme_id' => $scheme->id, 'year' => $y, 'month' => $m, 'status' => 'open'])->save();
                        $r['created']++;
                    } elseif ($p->matches($row, $settings->id)) {
                        $r['unchanged']++;
                    } elseif ($refresh && $p->isOpen()) {
                        $p->forceFill($attrs)->save();
                        $r['updated']++;
                    } else {
                        $r['kept']++; // differs from the settings but is not refreshed (not asked to, or already closed/locked)
                    }
                }

                // Periods of a cycle that the settings no longer have
                foreach ($existing->filter(fn ($p, $no) => $no > count($rows)) as $p) {
                    if ($refresh && $p->isOpen()) {
                        try {
                            $p->delete(); // a later table that uses the period (pay inputs...) has a restricting foreign key, so a used period is refused here
                            $r['removed']++;
                        } catch (QueryException) {
                            $r['extra']++;
                        }
                    } else {
                        $r['extra']++;
                    }
                }
            }

            Audit::log('pay_period.generated', $scheme, "Pay periods of {$scheme->name} for {$label}".($refresh ? ' (refreshed)' : ' generated'),
                context: ['tax_year' => $label, 'refresh' => $refresh] + array_diff_key($r, ['skipped' => 1]) + ['months_without_settings' => $r['skipped']]);

            return $r;
        });
    }

    public function close(PayPeriod $period, User $by): void
    {
        DB::transaction(function () use ($period, $by) {
            $p = PayPeriod::withoutGlobalScopes()->whereKey($period->id)->lockForUpdate()->firstOrFail();
            if ($p->status !== 'open') {
                throw ValidationException::withMessages(['period' => 'Only an open pay period can be closed.']);
            }
            $p->forceFill(['status' => 'closed', 'closed_at' => now(), 'closed_by' => $by->id, 'closed_by_name' => $by->name])->save();
            Audit::log('pay_period.closed', $p, "Pay period {$p->label()} closed ({$p->tax_year_label})", context: ['scheme_id' => $p->scheme_id]);
        });
    }

    public function reopen(PayPeriod $period, string $reason, User $by): void
    {
        if (trim($reason) === '') {
            throw ValidationException::withMessages(['reason' => 'Give a reason for reopening the pay period.']);
        }
        DB::transaction(function () use ($period, $reason, $by) {
            $p = PayPeriod::withoutGlobalScopes()->whereKey($period->id)->lockForUpdate()->firstOrFail();
            if ($p->status === 'locked') {
                throw ValidationException::withMessages(['period' => 'This pay period is locked by a pay run and cannot be reopened.']);
            }
            if ($p->status !== 'closed') {
                throw ValidationException::withMessages(['period' => 'Only a closed pay period can be reopened.']);
            }
            $p->forceFill(['status' => 'open', 'closed_at' => null, 'closed_by' => null, 'closed_by_name' => null])->save();
            Audit::log('pay_period.reopened', $p, "Pay period {$p->label()} reopened ({$p->tax_year_label})", context: ['scheme_id' => $p->scheme_id, 'reason' => trim($reason)]);
        });
    }

    /** For the pay run: a closed period becomes locked and can no longer be reopened. */
    public function lock(PayPeriod $period, ?User $by = null): void
    {
        DB::transaction(function () use ($period, $by) {
            $p = PayPeriod::withoutGlobalScopes()->whereKey($period->id)->lockForUpdate()->firstOrFail();
            if ($p->status !== 'closed') {
                throw ValidationException::withMessages(['period' => 'Only a closed pay period can be locked.']);
            }
            $p->forceFill(['status' => 'locked', 'locked_at' => now()])->save();
            Audit::log('pay_period.locked', $p, "Pay period {$p->label()} locked", context: ['scheme_id' => $p->scheme_id], actor: $by);
        });
    }

    /** Pay inputs (and anything else tied to a period) call this before they change data. */
    public static function assertOpen(PayPeriod $period): void
    {
        $fresh = PayPeriod::withoutGlobalScopes()->whereKey($period->id)->value('status');
        if ($fresh !== 'open') {
            throw ValidationException::withMessages(['period' => "Pay period {$period->label()} is {$fresh}, so it cannot be changed."]);
        }
    }
}
